package earth.terrarium.pastel.data.lang.guidebook.cuisine;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class ImbriferCookbookEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page0.text", "  *Chef Lorraine of Imbrifer*");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page0.title", "Imbrifer Fine Dining");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page1.text", "Welcome. Lets not get caught up with introductions - you're here because you want to learn how to cook, I can teach you. I studied in the Meriloux Culinary College, the finest culinary institution in the deep; I trained under the mentorship of Imperial Chef Aeverstrone, catering for the [#](ff3d71)scarlet moon bloodline[#](); I, with a team of my own apprentices, brought Imbrifer its first full-lotus restaurant. \\\n\\\n*Follow my lead and I'll teach you true taste.*");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page10.text", "\\\nI am not a brewer, and thus I cannot give much past the ingredients for Aqua Regia.\\\n\\\nBut I can note that, for the good chef, it is essential to understand your ingredients and how they are made. You cannot judge quality if you do not know how quality is created.");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page10.title", "An Essential Wine");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page11.text", "*Know your ingredients, learn them, understand them.*");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page2.text", "\\\nEverybody has to start somewhere, and for my students, this is that somewhere. Crawfish Cocktails are deceiving, they seem simple, but to truly master them takes finesse and practice. It is possible to flambé the peaches and spices to make a sweet, syrupy, spicy sauce without cooking the crawfish, but it demands an immense amount of care. I use this to filter new students.");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page2.title", "A Simple Entree");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page3.text", "*It can take hundreds of tries to get it right the first time.\\\n\\\nMany will crack before that.*");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page4.text", "\\\nBagnun is a culinary school classic. A heavily spiced, luxurious soup cut by a dollop of fresh cream; the contrast of scarlet, peppery soup and refreshing pearly cream makes a feast for the eyes and tongue alike. There was a woman I used to know of melochites. She loved a soup not too dissimilar to this one. We used to be good friends long ago, she called me egocentric.");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page4.title", "Melancholic Bisque");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page5.text", "    *.....*");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page6.text", "\\\nThe various plants of the Jade genus are generally desirable.\\\n\\\nTheir bulbs in particular are highly sought after, being alike onions in texture, but more delicate, sweet and ethereal in taste, earning them the moniker of truffles of the deep. This recipe makes use of a modern crossbreed of two native species - the striking [Jade Vine](entry://general/jade_vines).");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page6.title", "Soup of the Night");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page7.text", "*I've heard Jade Vine nectar has restorative properties...\\\n\\\nwhat a curious crossbreed.*");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page8.text", "\\\nIf anyone tells you that you need to cook fishcake, they're not just wrong, but also stupid. The proper way to prepare fishcake is to first spice and paste your fish, then let it ferment in a bath of nephrite vinegar for at least 72 hours. This will not just kill any parasites in the fish, but also cure the cake, giving it its signature pink color.");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page8.title", "Coy Koi Cold Cuts");
		provider.add("book.pastel.guidebook.imbrifer_cookbook.page9.text", "*The finest fishcake cures for months, if not years.*");
	}
}
